head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gInputRnd;
scwin.gIsurCd;
scwin.gAuthYn = 'N';
scwin.gParamObj = new Array(6);
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gPageSize = 10; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF35100.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};



// 특정 컬럼 숨기기
scwin.fn_Hidden_Col = function() {
    if (scwin.gLdMktTp == 1) {
        // 유가일때
        $c.cm.setColumnProp(grd_Grid, "NDESIGN_DECSN_DD", "Show", false); //미지정결정일자 를  hidden
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "COMITE_CASE_WRT", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "COMITE_WRTRPT_PROCS_STAT_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "WRT_DD", "Show", false);
    } else if (scwin.gLdMktTp == 2) {
        // 코스닥일때
        //grd_Grid.ColumnProp("COMITE_HLD_DD", "Show") = false;	// 위원회개최일을 hidden	
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "NO", "Suppress", '1'); // 번호
        $c.cm.setColumnProp(grd_Grid, "ISU_SRT_CD", "Suppress", '1'); // 종목코드
        $c.cm.setColumnProp(grd_Grid, "COM_ABBRV", "Suppress", '1'); // 회사명
        $c.cm.setColumnProp(grd_Grid, "LIST_STAT_NM", "Suppress", '1');
    } else if (scwin.gLdMktTp == 6) {
        // 코넥스일때
        //grd_Grid.ColumnProp("COMITE_HLD_DD", "Show") = false;	// 위원회개최일을 hidden	
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "NO", "Suppress", '1'); // 번호
        $c.cm.setColumnProp(grd_Grid, "ISU_SRT_CD", "Suppress", '1'); // 종목코드
        $c.cm.setColumnProp(grd_Grid, "COM_ABBRV", "Suppress", '1'); // 회사명
        $c.cm.setColumnProp(grd_Grid, "LIST_STAT_NM", "Suppress", '1');
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("검색 시작일을 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("검색 종료일을 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    var url_list = "/UnfaithfulDesignPreview.do?method=listUnfaithfulPreview&inputMessageId=NFAITHADVNOTIDCOND_IN" + "&outputMessageId=NFAITHADVNOTILIST_OUT";
    var url_cond = "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&SRCH_TP=" + $c.stf.getObjectValue(rdo_SrchTp) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    $c.cm.ShowWin(grd_Grid);
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(eval(obj), "ISUR_CD");
    scwin.gInputRnd = dts_nfaith_list.getCellData(eval(obj), "INPUT_RND");
    //alert("부모창:"+gAcptNo+","+ gIsurCd);

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DESIGN_ADVNOTI_DD") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "NFAITH_CONTN" || colid == "EINSPRUCH_CLS_DD") {
        var url = "/dsclmgt/ULDSTF35101.gfm";
        var winTitle = "불성실지정예고법인관리";
        //frame.CreateDialogFrame("gform1", url , winTitle ,100, 10, 1000, 800, "window" );
        await $c.frame.CreateFrame("nfaithinfo" + scwin.gAcptNo, url, winTitle, 200, 100, 560, 420 + 30, "window", 0, 0, true);
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "COMITE_CASE_WRT") {
        fn_PopupComiteCaseDetail();
    }

    function fn_PopupComiteCaseDetail() {
        var url = "/dsclmgt/ULDSTF37001.gfm?";
        url += "&ACPT_NO=" + scwin.gAcptNo;
        url += "&INPUT_RND=" + scwin.gInputRnd;
        url += "&ISUR_CD=" + scwin.gIsurCd;
        url += "&AUTH_YN=" + scwin.gAuthYn;
        url += "&frameID=" + frame.FrameID;
        if (fn_setParam(scwin.gAcptNo, scwin.gInputRnd, scwin.gIsurCd)) {
            // formal arguments
            $c.frame.path("../../").GWinOpen("ULDSTF37001", url, "불성실법인지정 안건작성", 100, 10, 820, 720 + 40, "");
        }
    };

    function fn_setParam() {
        // child에 param을 넘긴다.
        if (typeof(scwin.gParamObj) == "undefined") {
            $c.win.alert("전역변수 gParamObj를 선언하세요.");
            return false;
        }
        var argv = fn_setParam.arguments;
        var argc = fn_setParam.arguments.length;
        scwin.gParamObj = new Array(argc); // 초기화
        for (var i = 0; i < argc; i++) {
            // actual arguments
            eval("gParamObj.param" + i + " = argv[" + i + "]");
        }
        return true;
    };
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "불성실공시법인지정예고 목록", "", "8");
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_TeamList, js_dep_cd) ;		

};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_nfaith_list_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
    if (dts_nfaith_list.errorMsg) {
        $c.win.alert(dts_nfaith_list.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수
        //alert(txb_TotalCnt.value );

    }
};
scwin.dts_nfaith_list_OnLoadError = function() {
    $c.stf.alert_error(dts_nfaith_list);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    scwin.fn_Hidden_Col();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};
